from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); print('\\nFILE:',f.name[:-4]); page='?'
 hits=set()
 for i,l in enumerate(lines):
  if re.search(r'perpet|indefinit|(?:"'^|'"\\s)(?:\\d+[.)]?\\s*)?(?:term|duration)\\b|shall (?:continue|remain|expire)|agreement.{0,35}(?:years|months)',l,re.I):
   for j in range(max(0,i-1),min(len(lines),i+5)): hits.add(j)
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m[1]
  if i in hits: print(f'p{page}: {l}')
