/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
names=['GOCALL','GOLDRESOURCE','GULFSOUTH','Healthcentral','Impresse','Lifeway','MEDALIST','NETGROCER','OPTIMIZED','SPOK','Euromedia']
for f in sorted(Path('/docs').glob('*.txt')):
 if not any(f.name.startswith(n) for n in names):continue
 lines=f.read_text().splitlines();page='?';print('\\n'+f.name[:-4]);hits=set()
 for i,l in enumerate(lines):
  if re.search(r'\\bterm\\b|perpet|indefinit|expir|termination',l,re.I):
   if re.search(r'during|following|surviv|upon termination|after termination',l,re.I):continue
   hits.update(range(i,min(i+5,len(lines))))
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m:page=m[1]
  if i in hits:print('p'+page+': '+l)
PY"

